app.get('/orders', async (req, res) => {
  const page = Number(req.query.page) || 1;
  const limit = Number(req.query.limit) || 20;
  const orders = await Order.find({ status: req.query.status })
    .skip((page - 1) * limit)
    .limit(limit);
  res.json({ page, limit, data: orders });
});

